use std::collections::HashMap;
use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::error::{LayersError, Result};

/// Top-level configuration parsed from `layers.toml`.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct LayersConfig {
    #[serde(default)]
    pub daemon: DaemonConfig,
    #[serde(default)]
    pub agent: AgentConfig,
    #[serde(default)]
    pub channels: HashMap<String, ChannelConfig>,
    #[serde(default)]
    pub providers: HashMap<String, ProviderConfig>,
    #[serde(default)]
    pub tools: ToolsConfig,
    #[serde(default)]
    pub mcp: McpConfig,
    #[serde(default)]
    pub agents: HashMap<String, AgentConfigEntry>,
    #[serde(default)]
    pub bindings: Vec<BindingConfig>,
    #[serde(default)]
    pub brains: HashMap<String, BrainConfig>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DaemonConfig {
    #[serde(default = "default_bind_address")]
    pub bind_address: String,
    #[serde(default = "default_port")]
    pub port: u16,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub tls: Option<TlsConfig>,
}

impl Default for DaemonConfig {
    fn default() -> Self {
        Self {
            bind_address: default_bind_address(),
            port: default_port(),
            tls: None,
        }
    }
}

fn default_bind_address() -> String {
    "127.0.0.1".to_string()
}

fn default_port() -> u16 {
    3000
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BrainConfig {
    pub cli: String,
    #[serde(default)]
    pub args: Vec<String>,
    #[serde(default = "default_brain_output")]
    pub output: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub session_arg: Option<String>,
    #[serde(default)]
    pub needs_pty: bool,
    #[serde(default)]
    pub read_stderr: bool,
    #[serde(default)]
    pub pipe_stdin: bool,
}

fn default_brain_output() -> String {
    "text".to_string()
}

